mapper.select:
select x.id, x.business_date, x.account_date , x.loan_contract_code, x.periods, x.process_instance_id, x.is_generate_voucher, x.approve_error_info, x.period_code, x.process_status, eaatpd.asset_abs_transfer_payment_id, sum(coalesce(eaatpd.actual_principal_amount,0)+coalesce(eaatpd.actual_interest_amount,0)) as receivablesRentalAmount, sum(coalesce(eaatpd.actual_retention_purchase_amount,0)) as actual_retention_purchase_amount, sum(coalesce(eaatpd.actual_penalty_interest_amount,0)) as actual_penalty_interest_amount from eg_asset_abs_transfer_payment x inner join eg_asset_abs_transfer_payment_detail eaatpd on x.id = eaatpd.asset_abs_transfer_payment_id where 1 = 1
and x.loan_contract_code in
#{item}
and x.periods in
#{item}
and to_char(x.account_date,'YYYY-MM-DD') >= to_char(to_date(#{param.startAccountDate},'YYYY-MM-DD'),'YYYY-MM-DD')
and to_char(x.account_date,'YYYY-MM-DD') <= to_char(to_date(#{param.endAccountDate},'YYYY-MM-DD'),'YYYY-MM-DD')
and x.id = #{param.id}
group by x.id, x.business_date, x.account_date, x.loan_contract_code, x.periods, x.process_instance_id, x.is_generate_voucher, x.approve_error_info, x.period_code, x.process_status, eaatpd.asset_abs_transfer_payment_id

select * from eg_asset_abs_transfer_payment_detail eaatpd inner join eg_asset_abs_transfer_payment eaatp on eaatpd.asset_abs_transfer_payment_id = eaatp.id where 1 = 1 and eaatpd.del_flag = '0' and eaatp.del_flag = '0'
and eaatpd.contract_code = #{param.contractCode}
and eaatp.loan_contract_code = #{param.loanContractCode}
and eaatp.periods = #{param.periods}

